{
  "experiences": [
    {
      "turn": 1,
      "then_experience": "내과에서 '스트레스성이니 상담을 받아보라'는 말을 듣고 왔지만, 여기서 뭘 말해야 할지 모르겠고, 심각한 사람으로 취급받고 싶지 않다는 경계를 깔고 시작함.",
      "current_context": "세 번의 질문을 거치면서 증상 패턴을 사실적으로 설명하는 데는 어느 정도 편안함을 느끼고 있음. 감정적 해석 없이 '머릿속 내용'을 말하는 범주 안에서는 답할 수 있다는 감각이 생김.",
      "uncertainty": "상담사가 '밤에만 그런 건지, 낮에도 그런 건지'를 묻는 것은 단순 증상 확인인지, 아니면 이 패턴이 일상 전반에 퍼져 있다는 걸 드러내려는 건지 아직 모르겠음."
    },
    {
      "turn": 3,
      "then_experience": "잠들기까지 오래 걸린다는 패턴을 말하면서, 누우면 머리가 안 쉰다는 느낌을 짧게 덧붙임. 감정적 해석은 피하고 증상 설명 범주 안에서 답했음.",
      "current_context": "상담사가 '머리가 안 쉰다'는 표현을 받아 '퇴근을 못 하는 느낌'이라고 반영해 주었는데, 그 표현이 묘하게 정확해서 약간 찔림.",
      "uncertainty": "'낮에도 자주 그런 건지'라는 질문이 내 일 전체를 드러내라는 뜻이라면, 어디까지 말해야 할지 감이 안 옴."
    },
    {
      "turn": 4,
      "then_experience": "내일 수업이나 교재 같은 학원 일 생각이 돌고, 빠뜨린 거 없나 확인 안 한 거 없나 하는 생각이 계속 돈다고 말함. 아직 인간관계 갈등(강사 퇴사, 딸의 말)은 말할 준비가 아니라고 판단함.",
      "current_context": "상담사가 그 확인 루프를 '몸은 누워 있어도 머리는 퇴근을 못 하는 느낌'이라고 반영했는데, 그 표현이 내 상태를 정확히 짚은 것 같아서 조금 당황스러움.",
      "uncertainty": "낮에도 그렇다고 말하면, 그게 '성격'인지 '문제'인지 상담사가 어떻게 받아들일지 모르겠음. 아직은 '성격' 쪽으로 말하고 싶은데, 그게 회피처럼 들릴까 봐 걱정됨."
    }
  ]
}

